                        && self.source_location(value.range()).line != location.line
                        && matches!(value.as_ref(), Expr::BoolOp(boolean) if boolean.op == BoolOp::And)
                        && self
                            .control
                            .withs
                            .active_with_exits
                            .last()
                            .is_some_and(|context| !context.is_async)
