            && !statement.handlers.is_empty()
            && matches!(statement.body.last(), Some(Stmt::Return(_)))
            && statement.handlers.iter().all(|handler| {
                handler
                    .as_except_handler()
                    .is_some_and(|handler| matches!(handler.body.last(), Some(Stmt::Raise(_))))
            })
